import React, { useState } from 'react';
import { useOutletContext, Outlet, useLocation } from 'react-router-dom';
import ProjectNavbar from '../../components/ProjectNavbar';
import './Security.css'; 

const SecurityPage = () => {
  const context = useOutletContext();
  const location = useLocation();
  const isDashboard = location.pathname === '/sec';
  const { data: secData, setter: setSecData } = context?.sec || {};

  const [scanType, setScanType] = useState('static');
  const [scanning, setScanning] = useState(false);
  // States for feedback and display
  const [message, setMessage] = useState(null);
  const [scanResults, setScanResults] = useState(null);

  const runSecurityScan = async () => {
    setScanning(true);
    setMessage(null);
    setScanResults(null);
    try {
      const response = await fetch('http://localhost:8000/api/security/scan', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ type: scanType }),
      });
      
      if (!response.ok) throw new Error("Scan failed. Server error.");
      
      const data = await response.json();
      setScanResults(data);
      setMessage("Scan complete: System secured.");
      if (setSecData) setSecData(data); // Updates global state for P1-P4
    } catch (error) { 
      console.error(error);
      setMessage("Error: Failed to connect to security pipeline.");
    } finally { 
      setScanning(false); 
    }
  };

  return (
    <div className="soc-container">
      <ProjectNavbar basePath="sec" links={["Threats", "Logs", "Integrity", "VPC"]} />
      
      <div className="p-8">
        {isDashboard && (
          <div style={{ padding: '20px', fontFamily: 'sans-serif' }}>
            <header>
              <h2 style={{ fontSize: '1.5rem', marginBottom: '15px' }}>Security Operations Center (SOC)</h2>
              <div style={{ display: 'flex', gap: '10px', marginBottom: '20px' }}>
                <button 
                  className={`workspace-button ${scanType === 'static' ? 'active-tab' : 'inactive-tab'}`} 
                  onClick={() => setScanType('static')}
                >Static Scan</button>
                <button 
                  onClick={() => setScanType('dynamic')} 
                  style={{ padding: '10px 20px', backgroundColor: scanType === 'dynamic' ? '#38bdf8' : '#e2e8f0' }}
                >External Scan</button>
              </div>
            </header>

            <button 
              onClick={runSecurityScan} 
              disabled={scanning}
              style={{ padding: '12px 24px', backgroundColor: '#4f46e5', color: 'white', borderRadius: '6px' }}
            >
              {scanning ? 'Analyzing...' : 'Initiate Scan'}
            </button>
            
            {/* Error/Status Box */}
            {message && (
              <div style={{ 
                marginTop: '20px', padding: '15px', borderRadius: '6px',
                backgroundColor: message.includes("Error") ? '#fee2e2' : '#dcfce7',
                color: message.includes("Error") ? '#991b1b' : '#166534',
                border: message.includes("Error") ? '1px solid #fecaca' : '1px solid #bbf7d0'
              }}>
                {message}
              </div>
            )}

            {/* Data Result Box */}
            {scanResults && (
              <pre style={{ marginTop: '20px', padding: '15px', background: '#f1f5f9', borderRadius: '6px', overflowX: 'auto' }}>
                {JSON.stringify(scanResults, null, 2)}
              </pre>
            )}
          </div>
        )}
        <Outlet context={context} /> 
      </div>
    </div>
  );
};
export default SecurityPage;
